create table public.reports (id bigint generated always as identity primary key, created_at timestamptz not null default now(), kind text not null check (kind in ('link','message','phone','upi','email','qr')), scam_type text not null check (scam_type in ('bank_kyc','upi_refund','lottery_prize','job_offer','parcel_delivery','investment','impersonation','loan_app','other')), region text not null check (region in ('Andhra Pradesh','Arunachal Pradesh','Assam','Bihar','Chhattisgarh','Goa','Gujarat','Haryana','Himachal Pradesh','Jharkhand','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Manipur','Meghalaya','Mizoram','Nagaland','Odisha','Punjab','Rajasthan','Sikkim','Tamil Nadu','Telangana','Tripura','Uttar Pradesh','Uttarakhand','West Bengal','Delhi','Jammu and Kashmir','Ladakh','Other UT','Not sure')));
create table public.report_limits (h text not null, at timestamptz not null default now());
create index on public.report_limits (h, at);
alter table public.reports enable row level security;
alter table public.report_limits enable row level security;
create or replace function public.submit_report(p_kind text, p_scam text, p_region text) returns json language plpgsql security definer set search_path = public as $$ declare ip text; hh text; n int; begin ip := coalesce(split_part((current_setting('request.headers', true)::json)->>'x-forwarded-for', ',', 1), 'unknown'); hh := md5(ip || to_char(date_trunc('day', now()), 'YYYY-MM-DD') || 'pg-salt'); delete from report_limits where at < now() - interval '1 day'; select count(*) into n from report_limits where h = hh and at > now() - interval '1 hour'; if n >= 5 then return json_build_object('ok', false, 'error', 'rate_limited'); end if; insert into reports(kind, scam_type, region) values (p_kind, p_scam, p_region); insert into report_limits(h) values (hh); return json_build_object('ok', true); end $$;
create or replace function public.get_stats() returns json language sql security definer set search_path = public as $$ select json_build_object('total', (select count(*) from reports), 'last7', (select count(*) from reports where created_at > now() - interval '7 days'), 'by_scam', coalesce((select json_agg(json_build_object('k', scam_type, 'n', c) order by c desc) from (select scam_type, count(*) c from reports group by 1) s), '[]'::json), 'by_region', coalesce((select json_agg(json_build_object('k', region, 'n', c) order by c desc) from (select region, count(*) c from reports group by 1 order by 2 desc limit 10) s), '[]'::json), 'by_kind', coalesce((select json_agg(json_build_object('k', kind, 'n', c) order by c desc) from (select kind, count(*) c from reports group by 1) s), '[]'::json), 'by_day', coalesce((select json_agg(json_build_object('k', d, 'n', c) order by d) from (select created_at::date d, count(*) c from reports where created_at > now() - interval '14 days' group by 1) s), '[]'::json)) $$;
revoke all on function public.submit_report(text,text,text) from public;
revoke all on function public.get_stats() from public;
grant execute on function public.submit_report(text,text,text) to anon;
grant execute on function public.get_stats() to anon;
revoke all on public.reports from anon, authenticated;
revoke all on public.report_limits from anon, authenticated;
